    suspend fun getRandomAlbums(size: Int = 50): Result<List<Album>> {
        return cacheManager.getAlbums(
            key = "random_albums_$size",
            type = CacheTypes.ALBUM_LIST_TYPE
        ) {
            try {
                val (username, token, salt) = getAuthParams()
                // Obtener canciones aleatorias para extraer álbumes únicos
                val response = NavidromeClient.getApiService().getRandomSongs(
                    username = username,
                    token = token,
                    salt = salt,
                    version = "1.16.1",
                    client = "Castafiore",
                    size = size
                )

                if (response.isSuccessful) {
                    response.body()?.let { randomSongsResponse ->
                        val songs = randomSongsResponse.subsonicResponse.randomSongs?.song ?: emptyList()

                        // Extraer álbumes únicos de las canciones aleatorias
                        val uniqueAlbums = songs
                            .mapNotNull { song ->
                                // Crear objeto Album basado en la información de la canción
                                if (song.albumId != null && song.album != null) {
                                    Album(
                                        id = song.albumId!!,
                                        name = song.album!!,
                                        artist = song.artist ?: "Artista Desconocido",
                                        artistId = song.artistId ?: "",
                                        coverArt = song.coverArt,
                                        songCount = 0, // No tenemos esta información desde las canciones
                                        duration = 0, // No tenemos esta información desde las canciones
                                        created = "", // Esta propiedad no existe en Song
                                        year = song.year,
                                        genre = song.genre
                                    )
                                } else null
                            }
                            .distinctBy { it.id } // Eliminar álbumes duplicados
                            .shuffled() // Mezclar para mayor aleatoriedad

                        Result.success(uniqueAlbums)
                    } ?: Result.failure(Exception("Empty response"))
                } else {
                    Result.failure(Exception("HTTP Error: ${response.code()} - ${response.message()}"))
                }
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
    }
}

package com.arantec.castafiore.service

import android.app.Service
import android.content.Intent
import android.os.Binder
import android.os.IBinder
import android.support.v4.media.session.MediaSessionCompat
import android.support.v4.media.session.PlaybackStateCompat
import androidx.media.session.MediaButtonReceiver
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.google.android.exoplayer2.ExoPlayer
import com.google.android.exoplayer2.MediaItem

class MusicService : Service() {

    private lateinit var mediaSession: MediaSessionCompat
    private lateinit var musicRepository: MusicRepository
    private val binder = MusicBinder()
    private var exoPlayer: ExoPlayer? = null

    private var currentSong: Song? = null
    private var isPlaying = false
    private var currentPosition = 0L
    private var playlist = mutableListOf<Song>()
    private var currentIndex = 0
    private var repeatMode = RepeatMode.OFF

    // Enum para los modos de repetición
    enum class RepeatMode {
        OFF, ALL, ONE
    }

    // Listeners para cambios de estado
    private val playbackStateListeners = mutableListOf<(Boolean) -> Unit>()
    private val songChangeListeners = mutableListOf<(Song?) -> Unit>()

    companion object {
        private const val TAG = "MusicService"
        private const val MEDIA_SESSION_TAG = "CastafioreMediaSession"
    }

    inner class MusicBinder : Binder() {
        fun getService(): MusicService = this@MusicService
    }

    override fun onCreate() {
        super.onCreate()

        musicRepository = MusicRepository.getInstance(this)

        // Inicializar MediaSession
        mediaSession = MediaSessionCompat(this, MEDIA_SESSION_TAG).apply {
            setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS or
                MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS
            )
            setCallback(mediaSessionCallback)
            isActive = true
        }

        exoPlayer = ExoPlayer.Builder(this).build()
        exoPlayer?.addListener(object : com.google.android.exoplayer2.Player.Listener {
            override fun onPlaybackStateChanged(state: Int) {
                if (state == com.google.android.exoplayer2.Player.STATE_ENDED) {
                    when (repeatMode) {
                        RepeatMode.ONE -> {
                            // Repetir la canción actual
                            startNewSong()
                        }
                        RepeatMode.ALL -> {
                            // Si hay más canciones, avanzar; si no, volver al inicio
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else if (playlist.isNotEmpty()) {
                                // Volver al inicio de la lista
                                currentIndex = 0
                                currentSong = playlist[currentIndex]
                                notifySongChanged(currentSong)
                                startNewSong()
                            }
                        }
                        RepeatMode.OFF -> {
                            // Comportamiento original: avanzar o parar
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else {
                                // Fin de la cola, detener reproducción
                                isPlaying = false
                                updatePlaybackState()
                                notifyPlaybackStateChanged(false)
                            }
                        }
                    }
                }
            }
            override fun onMediaItemTransition(mediaItem: MediaItem?, reason: Int) {
                // Actualizar el mini player al cambiar de canción
                currentSong = playlist.getOrNull(currentIndex)
                notifySongChanged(currentSong)
            }
        })

        updatePlaybackState()
    }

    override fun onBind(intent: Intent): IBinder {
        return binder
    }

    override fun onDestroy() {
        exoPlayer?.release()
        exoPlayer = null
        mediaSession.release()
        playbackStateListeners.clear()
        songChangeListeners.clear()
        super.onDestroy()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        MediaButtonReceiver.handleIntent(mediaSession, intent)
        return START_NOT_STICKY
    }

    private val mediaSessionCallback = object : MediaSessionCompat.Callback() {
        override fun onPlay() {
            play()
        }

        override fun onPause() {
            pause()
        }

        override fun onStop() {
            stop()
        }

        override fun onSkipToNext() {
            next()
        }

        override fun onSkipToPrevious() {
            previous()
        }

        override fun onSeekTo(pos: Long) {
            seekTo(pos)
        }
    }

    // Métodos públicos para controlar la reproducción
    fun play() {
        // Solo reanudar si ya hay una canción preparada
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            // El reproductor ya está preparado, solo reanudar
            exoPlayer?.play()
        } else {
            // Preparar y reproducir nueva canción
            startNewSong()
        }

        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
    }

    private fun startNewSong() {
        val song = currentSong ?: return
        val serverUrl = musicRepository.serverUrl ?: return
        val (username, token, salt) = musicRepository.getAuthParams()
        val streamUrl = song.getStreamUrl(serverUrl, username, token, salt)
        val mediaItem = MediaItem.fromUri(streamUrl)
        exoPlayer?.setMediaItem(mediaItem)
        exoPlayer?.prepare()
        exoPlayer?.play()
    }

    fun resume() {
        // Método específico para reanudar sin reiniciar
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            exoPlayer?.play()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
        } else {
            // Si no está listo, llamar a play normal
            play()
        }
    }

    fun pause() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.pause()
    }

    fun stop() {
        isPlaying = false
        currentPosition = 0L
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.stop()
    }

    fun togglePlayPause() {
        if (isPlaying) {
            pause()
        } else {
            play()
        }
    }

    fun next() {
        if (currentIndex < playlist.size - 1) {
            currentIndex++
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
            }
        }
    }

    fun previous() {
        if (currentIndex > 0) {
            currentIndex--
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
            }
        }
    }

    fun seekTo(position: Long) {
        currentPosition = position
        updatePlaybackState()
        exoPlayer?.seekTo(position)
    }

    fun playQueue(songs: List<Song>, startIndex: Int = 0) {
        playlist.clear()
        playlist.addAll(songs)
        currentIndex = startIndex
        currentSong = if (songs.isNotEmpty()) songs[startIndex] else null
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
    }

    fun playSong(song: Song) {
        playlist.clear()
        playlist.add(song)
        currentIndex = 0
        currentSong = song
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
    }

    fun addToQueue(song: Song) {
        playlist.add(song)
        notifyQueueChanged(playlist.toList())
    }

    fun playNext(song: Song) {
        val insertPosition = currentIndex + 1
        if (insertPosition <= playlist.size) {
            playlist.add(insertPosition, song)
            notifyQueueChanged(playlist.toList())
        } else {
            // Si no hay posición siguiente válida, agregar al final
            addToQueue(song)
        }
    }

    fun removeFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            playlist.removeAt(index)
            if (index < currentIndex) {
                currentIndex--
            } else if (index == currentIndex && currentIndex >= playlist.size) {
                currentIndex = playlist.size - 1
                currentSong = if (playlist.isNotEmpty()) playlist[currentIndex] else null
                notifySongChanged(currentSong)
            }
            notifyQueueChanged(playlist.toList())
        }
    }

    // Nuevos métodos para la cola de reproducción
    fun getQueue(): List<Song> = playlist.toList()

    fun getCurrentIndex(): Int = currentIndex

    fun playFromQueue(index: Int) {
        if (index in 0 until playlist.size) {
            currentIndex = index
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)
            startNewSong()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
        }
    }

    fun clearQueue() {
        val hadSongs = playlist.isNotEmpty()
        playlist.clear()
        currentIndex = 0
        currentSong = null

        if (hadSongs) {
            stop()
            notifySongChanged(null)
            notifyQueueChanged(emptyList())
        }
    }

    fun moveInQueue(fromIndex: Int, toIndex: Int) {
        if (fromIndex in 0 until playlist.size && toIndex in 0 until playlist.size) {
            val song = playlist.removeAt(fromIndex)
            playlist.add(toIndex, song)

            // Actualizar currentIndex si es necesario
            when {
                fromIndex == currentIndex -> currentIndex = toIndex
                fromIndex < currentIndex && toIndex >= currentIndex -> currentIndex--
                fromIndex > currentIndex && toIndex <= currentIndex -> currentIndex++
            }

            notifyQueueChanged(playlist.toList())
        }
    }

    fun shuffleQueue() {
        if (playlist.isEmpty()) return

        // Obtener las canciones restantes (después de la actual)
        val remainingSongs = playlist.drop(currentIndex + 1).shuffled()

        // Reconstruir la playlist: canciones ya reproducidas + actual + restantes shuffled
        val playedSongs = playlist.take(currentIndex + 1)
        playlist.clear()
        playlist.addAll(playedSongs)
        playlist.addAll(remainingSongs)

        notifyQueueChanged(playlist.toList())
    }

    fun unshuffleQueue() {
        // Esta función requeriría mantener el orden original
        // Por simplicidad, no implementamos deshacer shuffle
        // En una app real guardarías el orden original
    }

    fun setRepeatMode(mode: RepeatMode) {
        repeatMode = mode
    }

    fun getRepeatMode(): RepeatMode = repeatMode

    // Getters para el estado actual
    fun getCurrentSong(): Song? = currentSong
    fun isPlaying(): Boolean = isPlaying
    fun getCurrentPosition(): Long = exoPlayer?.currentPosition ?: 0L
    fun getDuration(): Long = exoPlayer?.duration ?: 0L

    // Métodos públicos para registrar listeners (compatibilidad con ArtistDetailFragment)
    fun setOnSongChangeListener(listener: ((Song?) -> Unit)?) {
        songChangeListeners.clear()
        listener?.let { songChangeListeners.add(it) }
    }

    fun setOnPlaybackStateChangeListener(listener: ((Boolean) -> Unit)?) {
        playbackStateListeners.clear()
        listener?.let { playbackStateListeners.add(it) }
    }

    // Listeners para cambios de estado
    private val queueChangeListeners = mutableListOf<(List<Song>) -> Unit>()

    fun addPlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.add(listener)
    }

    fun addSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.add(listener)
    }

    fun addQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.add(listener)
    }

    fun removePlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.remove(listener)
    }

    fun removeSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.remove(listener)
    }

    fun removeQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.remove(listener)
    }

    private fun notifyPlaybackStateChanged(isPlaying: Boolean) {
        playbackStateListeners.forEach { it(isPlaying) }
    }

    private fun notifySongChanged(song: Song?) {
        songChangeListeners.forEach { it(song) }
    }

    private fun notifyQueueChanged(queue: List<Song>) {
        queueChangeListeners.forEach { it(queue) }
    }

    private fun updatePlaybackState() {
        val state = if (isPlaying) {
            PlaybackStateCompat.STATE_PLAYING
        } else {
            PlaybackStateCompat.STATE_PAUSED
        }

        val playbackState = PlaybackStateCompat.Builder()
            .setState(state, currentPosition, 1.0f)
            .setActions(
                PlaybackStateCompat.ACTION_PLAY_PAUSE or
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT or
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS or
                PlaybackStateCompat.ACTION_SEEK_TO
            )
            .build()

        mediaSession.setPlaybackState(playbackState)
    }
}

package com.arantec.castafiore.service

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.media.session.MediaButtonReceiver
import androidx.core.content.ContextCompat
import androidx.media.app.NotificationCompat.MediaStyle
import android.support.v4.media.MediaMetadataCompat
import android.app.Service
import android.os.Binder
import android.os.IBinder
import android.support.v4.media.session.MediaSessionCompat
import android.support.v4.media.session.PlaybackStateCompat
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.exoplayer2.ExoPlayer
import com.google.android.exoplayer2.MediaItem
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import android.content.pm.ServiceInfo

class MusicService : Service() {

    private lateinit var mediaSession: MediaSessionCompat
    private lateinit var musicRepository: MusicRepository
    private val binder = MusicBinder()
    private var exoPlayer: ExoPlayer? = null

    private var currentSong: Song? = null
    private var isPlaying = false
    private var currentPosition = 0L
    private var playlist = mutableListOf<Song>()
    private var currentIndex = 0
    private var repeatMode = RepeatMode.OFF

    // Enum para los modos de repetición
    enum class RepeatMode {
        OFF, ALL, ONE
    }

    // Listeners para cambios de estado
    private val playbackStateListeners = mutableListOf<(Boolean) -> Unit>()
    private val songChangeListeners = mutableListOf<(Song?) -> Unit>()

    companion object {
        private const val TAG = "MusicService"
        private const val MEDIA_SESSION_TAG = "CastafioreMediaSession"
        private const val NOTIFICATION_CHANNEL_ID = "playback_channel"
        private const val NOTIFICATION_ID = 2001
    }

    inner class MusicBinder : Binder() {
        fun getService(): MusicService = this@MusicService
    }

    override fun onCreate() {
        super.onCreate()

        musicRepository = MusicRepository.getInstance(this)

        createNotificationChannel()

        // Inicializar MediaSession
        mediaSession = MediaSessionCompat(this, MEDIA_SESSION_TAG).apply {
            setFlags(
                MediaSessionCompat.FLAG_HANDLES_MEDIA_BUTTONS or
                MediaSessionCompat.FLAG_HANDLES_TRANSPORT_CONTROLS
            )
            setCallback(mediaSessionCallback)
            isActive = true
        }

        exoPlayer = ExoPlayer.Builder(this).build()
        exoPlayer?.addListener(object : com.google.android.exoplayer2.Player.Listener {
            override fun onPlaybackStateChanged(state: Int) {
                if (state == com.google.android.exoplayer2.Player.STATE_ENDED) {
                    when (repeatMode) {
                        RepeatMode.ONE -> {
                            // Repetir la canción actual
                            startNewSong()
                        }
                        RepeatMode.ALL -> {
                            // Si hay más canciones, avanzar; si no, volver al inicio
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else if (playlist.isNotEmpty()) {
                                // Volver al inicio de la lista
                                currentIndex = 0
                                currentSong = playlist[currentIndex]
                                notifySongChanged(currentSong)
                                startNewSong()
                            }
                        }
                        RepeatMode.OFF -> {
                            // Comportamiento original: avanzar o parar
                            if (currentIndex < playlist.size - 1) {
                                next()
                            } else {
                                // Fin de la cola, detener reproducción
                                isPlaying = false
                                updatePlaybackState()
                                notifyPlaybackStateChanged(false)
                                showOrUpdateNotification()
                            }
                        }
                    }
                }
                // Actualizar notificación cuando ExoPlayer cambia a READY o BUFFERING
                showOrUpdateNotification()
            }
            override fun onMediaItemTransition(mediaItem: MediaItem?, reason: Int) {
                // Actualizar el mini player al cambiar de canción
                currentSong = playlist.getOrNull(currentIndex)
                updateMediaMetadata()
                notifySongChanged(currentSong)
                showOrUpdateNotification()
            }
        })

        updatePlaybackState()
        updateMediaMetadata()
    }

    override fun onBind(intent: Intent): IBinder {
        return binder
    }

    override fun onDestroy() {
        exoPlayer?.release()
        exoPlayer = null
        mediaSession.release()
        playbackStateListeners.clear()
        songChangeListeners.clear()
        super.onDestroy()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        MediaButtonReceiver.handleIntent(mediaSession, intent)
        return START_NOT_STICKY
    }

    private val mediaSessionCallback = object : MediaSessionCompat.Callback() {
        override fun onPlay() {
            play()
        }

        override fun onPause() {
            pause()
        }

        override fun onStop() {
            stop()
        }

        override fun onSkipToNext() {
            next()
        }

        override fun onSkipToPrevious() {
            previous()
        }

        override fun onSeekTo(pos: Long) {
            seekTo(pos)
        }
    }

    // Métodos públicos para controlar la reproducción
    fun play() {
        // Solo reanudar si ya hay una canción preparada
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            // El reproductor ya está preparado, solo reanudar
            exoPlayer?.play()
        } else {
            // Preparar y reproducir nueva canción
            startNewSong()
        }

        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    private fun startNewSong() {
        val song = currentSong ?: return
        val serverUrl = musicRepository.serverUrl ?: return
        val (username, token, salt) = musicRepository.getAuthParams()
        val streamUrl = song.getStreamUrl(serverUrl, username, token, salt)
        val mediaItem = MediaItem.fromUri(streamUrl)
        exoPlayer?.setMediaItem(mediaItem)
        exoPlayer?.prepare()
        exoPlayer?.play()
        updateMediaMetadata()
        showOrUpdateNotification()
    }

    fun resume() {
        // Método específico para reanudar sin reiniciar
        if (exoPlayer?.playbackState == com.google.android.exoplayer2.Player.STATE_READY) {
            exoPlayer?.play()
            isPlaying = true
            updatePlaybackState()
            notifyPlaybackStateChanged(true)
            showOrUpdateNotification()
        } else {
            // Si no está listo, llamar a play normal
            play()
        }
    }

    fun pause() {
        isPlaying = false
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.pause()
        showOrUpdateNotification()
    }

    fun stop() {
        isPlaying = false
        currentPosition = 0L
        updatePlaybackState()
        notifyPlaybackStateChanged(false)
        exoPlayer?.stop()
        stopForeground(true)
        (getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager).cancel(NOTIFICATION_ID)
        stopSelf()
    }

    fun togglePlayPause() {
        if (isPlaying) {
            pause()
        } else {
            play()
        }
    }

    fun next() {
        if (currentIndex < playlist.size - 1) {
            currentIndex++
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun previous() {
        if (currentIndex > 0) {
            currentIndex--
            currentSong = playlist[currentIndex]
            notifySongChanged(currentSong)

            // Usar startNewSong para preparar correctamente la nueva canción
            startNewSong()
            if (isPlaying) {
                updatePlaybackState()
                notifyPlaybackStateChanged(true)
                showOrUpdateNotification()
            }
        }
    }

    fun seekTo(position: Long) {
        currentPosition = position
        updatePlaybackState()
        exoPlayer?.seekTo(position)
    }

    fun playQueue(songs: List<Song>, startIndex: Int = 0) {
        playlist.clear()
        playlist.addAll(songs)
        currentIndex = startIndex
        currentSong = if (songs.isNotEmpty()) songs[startIndex] else null
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    fun playSong(song: Song) {
        playlist.clear()
        playlist.add(song)
        currentIndex = 0
        currentSong = song
        notifySongChanged(currentSong)
        notifyQueueChanged(playlist.toList())

        // Usar startNewSong para asegurar que se prepare correctamente
        startNewSong()
        isPlaying = true
        updatePlaybackState()
        notifyPlaybackStateChanged(true)
        showOrUpdateNotification()
    }

    // --- Notificación y metadata ---
    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                NOTIFICATION_CHANNEL_ID,
                getString(R.string.app_name),
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Reproducción de música"
                setSound(null, null)
                enableVibration(false)
            }
            val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            nm.createNotificationChannel(channel)
        }
    }

    private fun getContentPendingIntent(): PendingIntent? {
        // Abrir la app (actividad launcher) al tocar la notificación
        val launchIntent = packageManager.getLaunchIntentForPackage(packageName) ?: return null
        launchIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
        return PendingIntent.getActivity(
            this,
            0,
            launchIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or if (Build.VERSION.SDK_INT >= 23) PendingIntent.FLAG_IMMUTABLE else 0
        )
    }

    private fun buildBaseNotification(largeIcon: Bitmap? = null): NotificationCompat.Builder {
        val song = currentSong
        val title = song?.title ?: getString(R.string.app_name)
        val artist = song?.artist ?: ""

        val playPauseAction = NotificationCompat.Action(
            if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play,
            if (isPlaying) getString(R.string.pause) else getString(R.string.play),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_PLAY_PAUSE
            )
        )
        val prevAction = NotificationCompat.Action(
            R.drawable.ic_arrow_back,
            getString(R.string.previous),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS
            )
        )
        val nextAction = NotificationCompat.Action(
            R.drawable.ic_skip_next,
            getString(R.string.next),
            MediaButtonReceiver.buildMediaButtonPendingIntent(
                this,
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT
            )
        )

        val style = MediaStyle()
            .setMediaSession(mediaSession.sessionToken)
            .setShowActionsInCompactView(0, 1, 2)

        val builder = NotificationCompat.Builder(this, NOTIFICATION_CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_music_note)
            .setContentTitle(title)
            .setContentText(artist)
            .setContentIntent(getContentPendingIntent())
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .setCategory(Notification.CATEGORY_TRANSPORT)
            .setOnlyAlertOnce(true)
            .setColor(ContextCompat.getColor(this, R.color.primary))
            .setStyle(style)
            .addAction(prevAction)
            .addAction(playPauseAction)
            .addAction(nextAction)

        if (largeIcon != null) builder.setLargeIcon(largeIcon)

        return builder
    }

    private fun showOrUpdateNotification() {
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        val isForeground = isPlaying

        // Cargar carátula en background y actualizar notificación
        val song = currentSong
        if (song != null && musicRepository.serverUrl != null) {
            val (u, t, s) = musicRepository.getAuthParams()
            val coverUrl = song.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s)
            CoroutineScope(Dispatchers.IO).launch {
                val bitmap = try {
                    if (coverUrl != null) {
                        val future = com.bumptech.glide.Glide.with(this@MusicService)
                            .asBitmap()
                            .load(coverUrl)
                            .submit(256, 256)
                        future.get()
                    } else null
                } catch (_: Exception) { null }

                withContext(Dispatchers.Main) {
                    val notification = buildBaseNotification(bitmap).build()
                    if (isForeground) {
                        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                            startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                        } else {
                            startForeground(NOTIFICATION_ID, notification)
                        }
                    } else {
                        nm.notify(NOTIFICATION_ID, notification)
                        // Mantener notificación visible pero quitar foreground si está pausado
                        stopForeground(false)
                    }
                }
            }
        } else {
            val notification = buildBaseNotification(null).build()
            if (isForeground) {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    startForeground(NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                } else {
                    startForeground(NOTIFICATION_ID, notification)
                }
            } else {
                nm.notify(NOTIFICATION_ID, notification)
                stopForeground(false)
            }
        }
    }

    private fun updateMediaMetadata() {
        val song = currentSong ?: return
        val metadata = MediaMetadataCompat.Builder()
            .putString(MediaMetadataCompat.METADATA_KEY_TITLE, song.title)
            .putString(MediaMetadataCompat.METADATA_KEY_ARTIST, song.artist)
            .putString(MediaMetadataCompat.METADATA_KEY_ALBUM, song.album)
            .putLong(MediaMetadataCompat.METADATA_KEY_DURATION, (song.duration * 1000).toLong())
            .build()
        mediaSession.setMetadata(metadata)
    }

    // Getters para el estado actual
    fun getCurrentSong(): Song? = currentSong
    fun isPlaying(): Boolean = isPlaying
    fun getCurrentPosition(): Long = exoPlayer?.currentPosition ?: 0L
    fun getDuration(): Long = exoPlayer?.duration ?: 0L

    // Métodos públicos para registrar listeners (compatibilidad con ArtistDetailFragment)
    fun setOnSongChangeListener(listener: ((Song?) -> Unit)?) {
        songChangeListeners.clear()
        listener?.let { songChangeListeners.add(it) }
    }

    fun setOnPlaybackStateChangeListener(listener: ((Boolean) -> Unit)?) {
        playbackStateListeners.clear()
        listener?.let { playbackStateListeners.add(it) }
    }

    // Listeners para cambios de estado
    private val queueChangeListeners = mutableListOf<(List<Song>) -> Unit>()

    fun addPlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.add(listener)
    }

    fun addSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.add(listener)
    }

    fun addQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.add(listener)
    }

    fun removePlaybackStateListener(listener: (Boolean) -> Unit) {
        playbackStateListeners.remove(listener)
    }

    fun removeSongChangeListener(listener: (Song?) -> Unit) {
        songChangeListeners.remove(listener)
    }

    fun removeQueueChangeListener(listener: (List<Song>) -> Unit) {
        queueChangeListeners.remove(listener)
    }

    private fun notifyPlaybackStateChanged(isPlaying: Boolean) {
        playbackStateListeners.forEach { it(isPlaying) }
    }

    private fun notifySongChanged(song: Song?) {
        songChangeListeners.forEach { it(song) }
    }

    private fun notifyQueueChanged(queue: List<Song>) {
        queueChangeListeners.forEach { it(queue) }
    }

    private fun updatePlaybackState() {
        val state = if (isPlaying) {
            PlaybackStateCompat.STATE_PLAYING
        } else {
            PlaybackStateCompat.STATE_PAUSED
        }

        val playbackState = PlaybackStateCompat.Builder()
            .setState(state, currentPosition, 1.0f)
            .setActions(
                PlaybackStateCompat.ACTION_PLAY_PAUSE or
                PlaybackStateCompat.ACTION_SKIP_TO_NEXT or
                PlaybackStateCompat.ACTION_SKIP_TO_PREVIOUS or
                PlaybackStateCompat.ACTION_SEEK_TO
            )
            .build()

        mediaSession.setPlaybackState(playbackState)
    }
}

package com.arantec.castafiore.ui.adapters

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.core.view.isGone
import androidx.core.view.isVisible
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Artist
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.databinding.ItemSearchResultBinding
import com.arantec.castafiore.utils.ImageLoader

class SearchResultsAdapter(
    private val onSongClick: (Song) -> Unit,
    private val onAlbumClick: (Album) -> Unit,
    private val onArtistClick: (Artist) -> Unit,
    private val onSongMoreClick: (Song) -> Unit = {}
) : ListAdapter<SearchResultsAdapter.Item, SearchResultsAdapter.SearchResultViewHolder>(Diff) {

    sealed class Item {
        data class SongItem(val song: Song) : Item()
        data class AlbumItem(val album: Album) : Item()
        data class ArtistItem(val artist: Artist) : Item()
    }

    private var serverUrl: String = ""
    private var username: String = ""
    private var token: String = ""
    private var salt: String = ""

    fun updateAuth(serverUrl: String, username: String, token: String, salt: String) {
        this.serverUrl = serverUrl
        this.username = username
        this.token = token
        this.salt = salt
        notifyDataSetChanged()
    }

    fun submitData(items: List<Item>) {
        submitList(items)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SearchResultViewHolder {
        val binding = ItemSearchResultBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SearchResultViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SearchResultViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class SearchResultViewHolder(private val binding: ItemSearchResultBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(item: Item) {
            when (item) {
                is Item.SongItem -> bindSong(item.song)
                is Item.AlbumItem -> bindAlbum(item.album)
                is Item.ArtistItem -> bindArtist(item.artist)
            }
        }

        private fun bindSong(song: Song) {
            binding.tvTitle.text = song.title
            binding.tvType.text = "Canción"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = true
            binding.tvDuration.text = song.getFormattedDuration()
            binding.tvSubtitle.text = listOfNotNull(song.artist, song.album).joinToString(" • ")
            binding.btnMore.isVisible = true

            val coverUrl = song.getCoverArtUrl(serverUrl, username, token, salt)
            ImageLoader.loadThumbnail(
                binding.root.context,
                binding.ivArtwork,
                coverUrl
            )

            binding.root.setOnClickListener { onSongClick(song) }
            binding.btnMore.setOnClickListener { onSongMoreClick(song) }
        }

        private fun bindAlbum(album: Album) {
            binding.tvTitle.text = album.name
            binding.tvType.text = "Álbum"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = false
            binding.tvSubtitle.text = listOfNotNull(album.artist, album.year?.toString()).joinToString(" • ")
            binding.btnMore.isGone = true

            val coverUrl = album.getCoverArtUrl(serverUrl, username, token, salt)
            ImageLoader.loadThumbnail(
                binding.root.context,
                binding.ivArtwork,
                coverUrl
            )

            binding.root.setOnClickListener { onAlbumClick(album) }
        }

        private fun bindArtist(artist: Artist) {
            binding.tvTitle.text = artist.name
            binding.tvType.text = "Artista"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = false
            val albumsText = artist.albumCount?.let { "$it álbum(es)" }
            binding.tvSubtitle.text = albumsText ?: ""
            binding.btnMore.isGone = true

            val artistImageUrl = ImageLoader.buildArtistImageUrl(serverUrl, artist.id, username, token, salt, 300)
            // Cargar como circular para distinguir artistas
            ImageLoader.loadArtistImage(
                binding.root.context,
                binding.ivArtwork,
                artistImageUrl
            )

            binding.root.setOnClickListener { onArtistClick(artist) }
        }
    }

    private object Diff : DiffUtil.ItemCallback<Item>() {
        override fun areItemsTheSame(oldItem: Item, newItem: Item): Boolean {
            return when {
                oldItem is Item.SongItem && newItem is Item.SongItem -> oldItem.song.id == newItem.song.id
                oldItem is Item.AlbumItem && newItem is Item.AlbumItem -> oldItem.album.id == newItem.album.id
                oldItem is Item.ArtistItem && newItem is Item.ArtistItem -> oldItem.artist.id == newItem.artist.id
                else -> false
            }
        }

        override fun areContentsTheSame(oldItem: Item, newItem: Item): Boolean {
            return oldItem == newItem
        }
    }
}

package com.arantec.castafiore.ui.adapters

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.core.view.isGone
import androidx.core.view.isVisible
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Artist
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.databinding.ItemSearchResultBinding
import com.arantec.castafiore.utils.ImageLoader
import com.google.android.material.imageview.ShapeableImageView
import com.google.android.material.shape.RelativeCornerSize

class SearchResultsAdapter(
    private val onSongClick: (Song) -> Unit,
    private val onAlbumClick: (Album) -> Unit,
    private val onArtistClick: (Artist) -> Unit,
    private val onSongMoreClick: (Song) -> Unit = {}
) : ListAdapter<SearchResultsAdapter.Item, SearchResultsAdapter.SearchResultViewHolder>(Diff) {

    sealed class Item {
        data class SongItem(val song: Song) : Item()
        data class AlbumItem(val album: Album) : Item()
        data class ArtistItem(val artist: Artist) : Item()
    }

    private var serverUrl: String = ""
    private var username: String = ""
    private var token: String = ""
    private var salt: String = ""

    fun updateAuth(serverUrl: String, username: String, token: String, salt: String) {
        this.serverUrl = serverUrl
        this.username = username
        this.token = token
        this.salt = salt
        notifyDataSetChanged()
    }

    fun submitData(items: List<Item>) {
        submitList(items)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SearchResultViewHolder {
        val binding = ItemSearchResultBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SearchResultViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SearchResultViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class SearchResultViewHolder(private val binding: ItemSearchResultBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(item: Item) {
            when (item) {
                is Item.SongItem -> bindSong(item.song)
                is Item.AlbumItem -> bindAlbum(item.album)
                is Item.ArtistItem -> bindArtist(item.artist)
            }
        }

        private fun bindSong(song: Song) {
            binding.tvTitle.text = song.title
            binding.tvType.text = "Canción"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = true
            binding.tvDuration.text = song.getFormattedDuration()
            binding.tvSubtitle.text = listOfNotNull(song.artist, song.album).joinToString(" • ")
            binding.btnMore.isVisible = true

            // Restablecer a contenedor no circular por posible reciclado
            (binding.ivArtwork as? ShapeableImageView)?.let { iv ->
                iv.shapeAppearanceModel = iv.shapeAppearanceModel.toBuilder()
                    .setAllCornerSizes(0f)
                    .build()
            }

            val coverUrl = song.getCoverArtUrl(serverUrl, username, token, salt)
            ImageLoader.loadThumbnail(
                binding.root.context,
                binding.ivArtwork,
                coverUrl
            )

            binding.root.setOnClickListener { onSongClick(song) }
            binding.btnMore.setOnClickListener { onSongMoreClick(song) }
        }

        private fun bindAlbum(album: Album) {
            binding.tvTitle.text = album.name
            binding.tvType.text = "Álbum"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = false
            binding.tvSubtitle.text = listOfNotNull(album.artist, album.year?.toString()).joinToString(" • ")
            binding.btnMore.isGone = true

            // Restablecer a contenedor no circular por posible reciclado
            (binding.ivArtwork as? ShapeableImageView)?.let { iv ->
                iv.shapeAppearanceModel = iv.shapeAppearanceModel.toBuilder()
                    .setAllCornerSizes(0f)
                    .build()
            }

            val coverUrl = album.getCoverArtUrl(serverUrl, username, token, salt)
            ImageLoader.loadThumbnail(
                binding.root.context,
                binding.ivArtwork,
                coverUrl
            )

            binding.root.setOnClickListener { onAlbumClick(album) }
        }

        private fun bindArtist(artist: Artist) {
            binding.tvTitle.text = artist.name
            binding.tvType.text = "Artista"
            binding.tvType.isVisible = true
            binding.tvDuration.isVisible = false
            val albumsText = artist.albumCount?.let { "$it álbum(es)" }
            binding.tvSubtitle.text = albumsText ?: ""
            binding.btnMore.isGone = true

            // Hacer el contenedor circular (50% del tamaño)
            (binding.ivArtwork as? ShapeableImageView)?.let { iv ->
                iv.shapeAppearanceModel = iv.shapeAppearanceModel.toBuilder()
                    .setAllCornerSizes(RelativeCornerSize(0.5f))
                    .build()
            }

            val artistImageUrl = ImageLoader.buildArtistImageUrl(serverUrl, artist.id, username, token, salt, 300)
            // Cargar como circular para distinguir artistas
            ImageLoader.loadArtistImage(
                binding.root.context,
                binding.ivArtwork,
                artistImageUrl
            )

            binding.root.setOnClickListener { onArtistClick(artist) }
        }
    }

    private object Diff : DiffUtil.ItemCallback<Item>() {
        override fun areItemsTheSame(oldItem: Item, newItem: Item): Boolean {
            return when {
                oldItem is Item.SongItem && newItem is Item.SongItem -> oldItem.song.id == newItem.song.id
                oldItem is Item.AlbumItem && newItem is Item.AlbumItem -> oldItem.album.id == newItem.album.id
                oldItem is Item.ArtistItem && newItem is Item.ArtistItem -> oldItem.artist.id == newItem.artist.id
                else -> false
            }
        }

        override fun areContentsTheSame(oldItem: Item, newItem: Item): Boolean {
            return oldItem == newItem
        }
    }
}

package com.arantec.castafiore.ui.fragments

import android.app.Activity
import android.content.Intent
import android.os.Bundle
import android.speech.RecognizerIntent
import android.text.Editable
import android.text.TextWatcher
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.AccelerateDecelerateInterpolator
import android.view.inputmethod.EditorInfo
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.view.isGone
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Artist
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.FragmentSearchBinding
import com.arantec.castafiore.ui.adapters.SearchResultsAdapter
import com.google.android.material.snackbar.Snackbar
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import java.util.*

// Nuevos imports para servicio y opciones
import android.content.ComponentName
import android.content.Context
import android.content.ServiceConnection
import android.os.IBinder
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.dialogs.SongOptionsBottomSheet
import com.arantec.castafiore.ui.dialogs.PlaylistSelectorBottomSheet
import com.arantec.castafiore.data.download.SongDownloadManager

class SearchFragment : Fragment() {

    companion object {
        private const val SEARCH_DELAY_MS = 350L
        private const val ANIMATION_DURATION = 250L
    }

    private var _binding: FragmentSearchBinding? = null
    private val binding get() = _binding!!

    private lateinit var musicRepository: MusicRepository
    private lateinit var searchAdapter: SearchResultsAdapter

    // Estado de búsqueda
    private var searchJob: Job? = null
    private var currentSearchQuery = ""
    private var isVoiceSearchActive = false
    private var currentViewMode = ViewMode.RESULTS

    private var authUsername: String? = null
    private var authToken: String? = null
    private var authSalt: String? = null
    private var serverUrl: String? = null

    // Servicio de música
    private var musicService: MusicService? = null
    private var isBound = false
    private var pendingPlaySong: Song? = null

    private val voiceSearchLauncher = registerForActivityResult(
        ActivityResultContracts.StartActivityForResult()
    ) { result ->
        handleVoiceSearchResult(result.resultCode, result.data)
    }

    enum class ViewMode {
        SUGGESTIONS,
        HISTORY,
        RESULTS
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentSearchBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())
        serverUrl = musicRepository.serverUrl

        setupUI()
        setupRecycler()
        setupSearchFunctionality()
    }

    override fun onStart() {
        super.onStart()
        // Enlazar servicio para poder reproducir
        val intent = Intent(requireContext(), MusicService::class.java)
        requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    override fun onStop() {
        super.onStop()
        if (isBound) {
            requireContext().unbindService(serviceConnection)
            isBound = false
        }
    }

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as? MusicService.MusicBinder
            musicService = binder?.getService()
            isBound = true
            // Si había una canción pendiente, reproducir ahora
            pendingPlaySong?.let { song ->
                musicService?.playSong(song)
                pendingPlaySong = null
            }
        }
        override fun onServiceDisconnected(name: ComponentName?) {
            isBound = false
            musicService = null
        }
    }

    private fun setupUI() {
        // Animación de entrada
        binding.root.alpha = 0f
        binding.root.translationY = -100f
        binding.root.animate()
            .alpha(1f)
            .translationY(0f)
            .setDuration(ANIMATION_DURATION)
            .setInterpolator(AccelerateDecelerateInterpolator())
            .start()

        // Estados iniciales
        showEmptyState()

        // Botón limpiar
        binding.btnClearSearch.setOnClickListener {
            binding.etSearch.setText("")
        }

        // Retry en error
        binding.btnRetry.setOnClickListener {
            performSearch(currentSearchQuery)
        }
    }

    private fun setupRecycler() {
        searchAdapter = SearchResultsAdapter(
            onSongClick = { song -> onSongSelected(song) },
            onAlbumClick = { album -> onAlbumSelected(album) },
            onArtistClick = { artist -> onArtistSelected(artist) },
            onSongMoreClick = { song -> showSongOptions(song) }
        )
        binding.rvSearchResults.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = searchAdapter
            setHasFixedSize(true)
        }
    }

    private fun setupSearchFunctionality() {
        // EditText del layout real
        binding.etSearch.addTextChangedListener(object : TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                val query = s?.toString()?.trim() ?: ""
                binding.btnClearSearch.isVisible = query.isNotEmpty()
                handleSearchTextChange(query)
            }
            override fun afterTextChanged(s: Editable?) {}
        })

        binding.etSearch.setOnEditorActionListener { _, actionId, _ ->
            if (actionId == EditorInfo.IME_ACTION_SEARCH) {
                performSearch(binding.etSearch.text.toString().trim())
                true
            } else false
        }
    }

    private fun ensureAuth() {
        if (authUsername == null || authToken == null || authSalt == null) {
            try {
                val (u, t, s) = musicRepository.getAuthParams()
                authUsername = u
                authToken = t
                authSalt = s
            } catch (_: Exception) {
                // No configurado
            }
        }
    }

    private fun handleSearchTextChange(query: String) {
        currentSearchQuery = query
        searchJob?.cancel()

        if (query.isBlank()) {
            // Volver a estado vacío/historial
            showEmptyState()
            searchAdapter.submitData(emptyList<SearchResultsAdapter.Item>())
            return
        }

        // Debounce
        searchJob = lifecycleScope.launch {
            delay(SEARCH_DELAY_MS)
            if (query == currentSearchQuery) {
                performSearch(query)
            }
        }
    }

    private fun performSearch(query: String) {
        if (query.isBlank()) return
        if (!musicRepository.isConfigured()) {
            showErrorState(
                title = getString(R.string.app_name),
                message = "Configura tu servidor en Ajustes para buscar"
            )
            return
        }

        ensureAuth()
        showLoading(true)

        lifecycleScope.launch {
            val result = musicRepository.searchMusic(query)
            result.onSuccess { (songs, albums, artists) ->
                val items = mutableListOf<SearchResultsAdapter.Item>()
                artists.forEach { items.add(SearchResultsAdapter.Item.ArtistItem(it)) }
                albums.forEach { items.add(SearchResultsAdapter.Item.AlbumItem(it)) }
                songs.forEach { items.add(SearchResultsAdapter.Item.SongItem(it)) }

                if (items.isEmpty()) {
                    showErrorState(
                        title = "Sin resultados",
                        message = "Intenta con otros términos"
                    )
                } else {
                    showResults()
                    searchAdapter.updateAuth(
                        serverUrl = serverUrl ?: "",
                        username = authUsername ?: "",
                        token = authToken ?: "",
                        salt = authSalt ?: ""
                    )
                    searchAdapter.submitData(items)
                }
            }.onFailure { e ->
                showErrorState(
                    title = "Error",
                    message = e.message ?: "Error al buscar"
                )
            }
            showLoading(false)
        }
    }

    private fun onSongSelected(song: Song) {
        // Reproducir canción usando el servicio
        musicService?.playSong(song) ?: run {
            pendingPlaySong = song
            val intent = Intent(requireContext(), MusicService::class.java)
            requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
            Toast.makeText(requireContext(), "Iniciando reproductor...", Toast.LENGTH_SHORT).show()
        }
    }

    private fun onAlbumSelected(album: Album) {
        // Navegar a detalle de álbum con Safe Args
        val action = SearchFragmentDirections.actionSearchToAlbumDetail(album)
        findNavController().navigate(action)
    }

    private fun onArtistSelected(artist: Artist) {
        // Navegar a detalle de artista con Safe Args
        val action = SearchFragmentDirections.actionSearchToArtistDetail(
            artistId = artist.id,
            artistName = artist.name
        )
        findNavController().navigate(action)
    }

    private fun showSongOptions(song: Song) {
        val bottomSheet = SongOptionsBottomSheet
            .newInstance(song)
            .setOnDownloadClickListener { s ->
                SongDownloadManager.getInstance(requireContext()).downloadSong(s)
            }
            .setOnDeleteDownloadClickListener { s ->
                val ok = SongDownloadManager.getInstance(requireContext()).deleteSong(s.id)
                if (!ok) Toast.makeText(requireContext(), "No se pudo eliminar la descarga", Toast.LENGTH_SHORT).show()
            }
            .setOnAddToQueueClickListener { s ->
                musicService?.addToQueue(s)
            }
            .setOnPlayNextClickListener { s ->
                musicService?.playNext(s)
            }
            .setOnAddToPlaylistClickListener { s ->
                PlaylistSelectorBottomSheet.newInstance(s)
                    .show(childFragmentManager, "playlistSelector")
            }
            .setOnViewAlbumClickListener { s ->
                val albumId = s.albumId
                if (!albumId.isNullOrEmpty()) {
                    viewLifecycleOwner.lifecycleScope.launch {
                        musicRepository.getAlbumDetail(albumId).fold(
                            onSuccess = { album ->
                                val action = SearchFragmentDirections.actionSearchToAlbumDetail(album)
                                findNavController().navigate(action)
                            },
                            onFailure = {
                                Toast.makeText(requireContext(), "No se pudo abrir el álbum", Toast.LENGTH_SHORT).show()
                            }
                        )
                    }
                } else {
                    Toast.makeText(requireContext(), "Álbum no disponible", Toast.LENGTH_SHORT).show()
                }
            }
            .setOnViewArtistClickListener { s ->
                val artistId = s.artistId
                if (!artistId.isNullOrEmpty()) {
                    val action = SearchFragmentDirections.actionSearchToArtistDetail(artistId, s.artist)
                    findNavController().navigate(action)
                } else {
                    Toast.makeText(requireContext(), "Artista no disponible", Toast.LENGTH_SHORT).show()
                }
            }
        bottomSheet.show(childFragmentManager, "songOptions")
    }

    private fun startVoiceSearch() {
        try {
            isVoiceSearchActive = true
            val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
                putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
                putExtra(RecognizerIntent.EXTRA_LANGUAGE, Locale.getDefault())
                putExtra(RecognizerIntent.EXTRA_PROMPT, "Habla ahora...")
                putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)
            }
            voiceSearchLauncher.launch(intent)
        } catch (_: Exception) {
            isVoiceSearchActive = false
            Toast.makeText(context, "Búsqueda por voz no soportada", Toast.LENGTH_SHORT).show()
        }
    }

    private fun handleVoiceSearchResult(resultCode: Int, data: Intent?) {
        isVoiceSearchActive = false
        if (resultCode == Activity.RESULT_OK && data != null) {
            val results = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)
            if (!results.isNullOrEmpty()) {
                val spokenText = results[0]
                binding.etSearch.setText(spokenText)
                binding.etSearch.setSelection(spokenText.length)
                performSearch(spokenText)
            }
        }
    }

    private fun switchToViewMode(mode: ViewMode) {
        if (currentViewMode == mode) return
        currentViewMode = mode
        // Animación ligera
        binding.rvSearchResults.animate()
            .alpha(0.5f)
            .setDuration(ANIMATION_DURATION / 2)
            .withEndAction {
                binding.rvSearchResults.animate().alpha(1f).setDuration(ANIMATION_DURATION / 2).start()
            }
            .start()
    }

    private fun showLoading(show: Boolean) {
        binding.loadingState.isVisible = show
        if (show) {
            // Al mostrar loading, ocultar todo lo demás
            binding.rvSearchResults.isGone = true
            binding.emptyState.isGone = true
            binding.errorState.isGone = true
        }
        // Cuando show es false, no cambiamos otros estados; quienes llamen a este método
        // deben haber mostrado el estado correcto (resultados, error o vacío).
    }

    private fun showEmptyState() {
        binding.emptyState.isVisible = true
        binding.loadingState.isGone = true
        binding.rvSearchResults.isGone = true
        binding.errorState.isGone = true
    }

    private fun showResults() {
        binding.rvSearchResults.isVisible = true
        binding.emptyState.isGone = true
        binding.loadingState.isGone = true
        binding.errorState.isGone = true
        switchToViewMode(ViewMode.RESULTS)
    }

    private fun showErrorState(title: String, message: String) {
        binding.tvErrorTitle.text = title
        binding.tvErrorMessage.text = message
        binding.errorState.isVisible = true
        binding.emptyState.isGone = true
        binding.loadingState.isGone = true
        binding.rvSearchResults.isGone = true
    }

    private fun showSnackbar(message: String, isError: Boolean = false) {
        val snackbar = Snackbar.make(binding.root, message, Snackbar.LENGTH_SHORT)
        if (isError) {
            // Usa color por defecto de Material si no existe R.color.error
        }
        snackbar.show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        searchJob?.cancel()
        _binding = null
    }
}

package com.arantec.castafiore.ui.fragments

import android.app.Activity
import android.content.Intent
import android.os.Bundle
import android.speech.RecognizerIntent
import android.text.Editable
import android.text.TextWatcher
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.AccelerateDecelerateInterpolator
import android.view.inputmethod.EditorInfo
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.view.isGone
import androidx.core.view.isVisible
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.lifecycle.lifecycleScope
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.arantec.castafiore.R
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Artist
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.FragmentSearchBinding
import com.arantec.castafiore.ui.adapters.SearchResultsAdapter
import com.arantec.castafiore.ui.viewmodels.SearchViewModel
import com.google.android.material.snackbar.Snackbar
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import java.util.*

// Nuevos imports para servicio y opciones
import android.content.ComponentName
import android.content.Context
import android.content.ServiceConnection
import android.os.IBinder
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.ui.dialogs.SongOptionsBottomSheet
import com.arantec.castafiore.ui.dialogs.PlaylistSelectorBottomSheet
import com.arantec.castafiore.data.download.SongDownloadManager

class SearchFragment : Fragment() {

    companion object {
        private const val SEARCH_DELAY_MS = 350L
        private const val ANIMATION_DURATION = 250L
    }

    private var _binding: FragmentSearchBinding? = null
    private val binding get() = _binding!!

    private lateinit var musicRepository: MusicRepository
    private lateinit var searchAdapter: SearchResultsAdapter
    private val viewModel: SearchViewModel by viewModels()

    // Estado de búsqueda
    private var searchJob: Job? = null
    private var currentSearchQuery = ""
    private var isVoiceSearchActive = false
    private var currentViewMode = ViewMode.RESULTS

    private var authUsername: String? = null
    private var authToken: String? = null
    private var authSalt: String? = null
    private var serverUrl: String? = null

    // Servicio de música
    private var musicService: MusicService? = null
    private var isBound = false
    private var pendingPlaySong: Song? = null

    private val voiceSearchLauncher = registerForActivityResult(
        ActivityResultContracts.StartActivityForResult()
    ) { result ->
        handleVoiceSearchResult(result.resultCode, result.data)
    }

    enum class ViewMode {
        SUGGESTIONS,
        HISTORY,
        RESULTS
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentSearchBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())
        serverUrl = musicRepository.serverUrl

        setupUI()
        setupRecycler()
        setupSearchFunctionality()

        // Restaurar resultados si existen en ViewModel para evitar parpadeo
        ensureAuth()
        val cachedItems = viewModel.items.value.orEmpty()
        val cachedQuery = viewModel.query.value ?: ""
        if (cachedItems.isNotEmpty()) {
            searchAdapter.updateAuth(
                serverUrl = serverUrl ?: "",
                username = authUsername ?: "",
                token = authToken ?: "",
                salt = authSalt ?: ""
            )
            searchAdapter.submitData(cachedItems)
            showResults()
            // Rellenar el texto sin disparar el watcher
            suppressTextWatcher = true
            binding.etSearch.setText(cachedQuery)
            binding.etSearch.setSelection(cachedQuery.length)
            suppressTextWatcher = false
        } else {
            if (cachedQuery.isNotBlank()) {
                // Si hay query pero no items, disparar búsqueda sin mostrar estado vacío
                showLoading(true)
                performSearch(cachedQuery)
            } else {
                showEmptyState()
            }
        }
    }

    override fun onStart() {
        super.onStart()
        // Enlazar servicio para poder reproducir
        val intent = Intent(requireContext(), MusicService::class.java)
        requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
    }

    override fun onStop() {
        super.onStop()
        if (isBound) {
            requireContext().unbindService(serviceConnection)
            isBound = false
        }
    }

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as? MusicService.MusicBinder
            musicService = binder?.getService()
            isBound = true
            // Si había una canción pendiente, reproducir ahora
            pendingPlaySong?.let { song ->
                musicService?.playSong(song)
                pendingPlaySong = null
            }
        }
        override fun onServiceDisconnected(name: ComponentName?) {
            isBound = false
            musicService = null
        }
    }

    private fun setupUI() {
        // Animación de entrada
        binding.root.alpha = 0f
        binding.root.translationY = -100f
        binding.root.animate()
            .alpha(1f)
            .translationY(0f)
            .setDuration(ANIMATION_DURATION)
            .setInterpolator(AccelerateDecelerateInterpolator())
            .start()

        // No llamar showEmptyState() aquí; se decide en onViewCreated según ViewModel

        // Botón limpiar
        binding.btnClearSearch.setOnClickListener {
            binding.etSearch.setText("")
        }

        // Retry en error
        binding.btnRetry.setOnClickListener {
            performSearch(currentSearchQuery)
        }
    }

    private fun setupRecycler() {
        searchAdapter = SearchResultsAdapter(
            onSongClick = { song -> onSongSelected(song) },
            onAlbumClick = { album -> onAlbumSelected(album) },
            onArtistClick = { artist -> onArtistSelected(artist) },
            onSongMoreClick = { song -> showSongOptions(song) }
        )
        binding.rvSearchResults.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = searchAdapter
            setHasFixedSize(true)
        }
    }

    private var suppressTextWatcher = false

    private fun setupSearchFunctionality() {
        binding.etSearch.addTextChangedListener(object : TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                if (suppressTextWatcher) return
                val query = s?.toString()?.trim() ?: ""
                binding.btnClearSearch.isVisible = query.isNotEmpty()
                handleSearchTextChange(query)
            }
            override fun afterTextChanged(s: Editable?) {}
        })

        binding.etSearch.setOnEditorActionListener { _, actionId, _ ->
            if (actionId == EditorInfo.IME_ACTION_SEARCH) {
                performSearch(binding.etSearch.text.toString().trim())
                true
            } else false
        }
    }

    private fun ensureAuth() {
        if (authUsername == null || authToken == null || authSalt == null) {
            try {
                val (u, t, s) = musicRepository.getAuthParams()
                authUsername = u
                authToken = t
                authSalt = s
            } catch (_: Exception) {
                // No configurado
            }
        }
    }

    private fun handleSearchTextChange(query: String) {
        currentSearchQuery = query
        viewModel.query.value = query
        searchJob?.cancel()

        if (query.isBlank()) {
            // Volver a estado vacío/historial
            showEmptyState()
            searchAdapter.submitData(emptyList<SearchResultsAdapter.Item>())
            return
        }

        // Debounce
        searchJob = lifecycleScope.launch {
            delay(SEARCH_DELAY_MS)
            if (query == currentSearchQuery) {
                performSearch(query)
            }
        }
    }

    private fun performSearch(query: String) {
        if (query.isBlank()) return
        if (!musicRepository.isConfigured()) {
            showErrorState(
                title = getString(R.string.app_name),
                message = "Configura tu servidor en Ajustes para buscar"
            )
            return
        }

        ensureAuth()
        showLoading(true)

        lifecycleScope.launch {
            val result = musicRepository.searchMusic(query)
            result.onSuccess { (songs, albums, artists) ->
                val items = mutableListOf<SearchResultsAdapter.Item>()
                artists.forEach { items.add(SearchResultsAdapter.Item.ArtistItem(it)) }
                albums.forEach { items.add(SearchResultsAdapter.Item.AlbumItem(it)) }
                songs.forEach { items.add(SearchResultsAdapter.Item.SongItem(it)) }

                if (items.isEmpty()) {
                    showErrorState(
                        title = "Sin resultados",
                        message = "Intenta con otros términos"
                    )
                } else {
                    // Guardar en ViewModel y mostrar
                    viewModel.items.value = items
                    viewModel.query.value = query
                    showResults()
                    searchAdapter.updateAuth(
                        serverUrl = serverUrl ?: "",
                        username = authUsername ?: "",
                        token = authToken ?: "",
                        salt = authSalt ?: ""
                    )
                    searchAdapter.submitData(items)
                }
            }.onFailure { e ->
                showErrorState(
                    title = "Error",
                    message = e.message ?: "Error al buscar"
                )
            }
            showLoading(false)
        }
    }

    private fun onSongSelected(song: Song) {
        // Reproducir canción usando el servicio
        musicService?.playSong(song) ?: run {
            pendingPlaySong = song
            val intent = Intent(requireContext(), MusicService::class.java)
            requireContext().bindService(intent, serviceConnection, Context.BIND_AUTO_CREATE)
            Toast.makeText(requireContext(), "Iniciando reproductor...", Toast.LENGTH_SHORT).show()
        }
    }

    private fun onAlbumSelected(album: Album) {
        // Navegar a detalle de álbum con Safe Args
        val action = SearchFragmentDirections.actionSearchToAlbumDetail(album)
        findNavController().navigate(action)
    }

    private fun onArtistSelected(artist: Artist) {
        // Navegar a detalle de artista con Safe Args
        val action = SearchFragmentDirections.actionSearchToArtistDetail(
            artistId = artist.id,
            artistName = artist.name
        )
        findNavController().navigate(action)
    }

    private fun showSongOptions(song: Song) {
        val bottomSheet = SongOptionsBottomSheet
            .newInstance(song)
            .setOnDownloadClickListener { s ->
                SongDownloadManager.getInstance(requireContext()).downloadSong(s)
            }
            .setOnDeleteDownloadClickListener { s ->
                val ok = SongDownloadManager.getInstance(requireContext()).deleteSong(s.id)
                if (!ok) Toast.makeText(requireContext(), "No se pudo eliminar la descarga", Toast.LENGTH_SHORT).show()
            }
            .setOnAddToQueueClickListener { s ->
                musicService?.addToQueue(s)
            }
            .setOnPlayNextClickListener { s ->
                musicService?.playNext(s)
            }
            .setOnAddToPlaylistClickListener { s ->
                PlaylistSelectorBottomSheet.newInstance(s)
                    .show(childFragmentManager, "playlistSelector")
            }
            .setOnViewAlbumClickListener { s ->
                val albumId = s.albumId
                if (!albumId.isNullOrEmpty()) {
                    viewLifecycleOwner.lifecycleScope.launch {
                        musicRepository.getAlbumDetail(albumId).fold(
                            onSuccess = { album ->
                                val action = SearchFragmentDirections.actionSearchToAlbumDetail(album)
                                findNavController().navigate(action)
                            },
                            onFailure = {
                                Toast.makeText(requireContext(), "No se pudo abrir el álbum", Toast.LENGTH_SHORT).show()
                            }
                        )
                    }
                } else {
                    Toast.makeText(requireContext(), "Álbum no disponible", Toast.LENGTH_SHORT).show()
                }
            }
            .setOnViewArtistClickListener { s ->
                val artistId = s.artistId
                if (!artistId.isNullOrEmpty()) {
                    val action = SearchFragmentDirections.actionSearchToArtistDetail(artistId, s.artist)
                    findNavController().navigate(action)
                } else {
                    Toast.makeText(requireContext(), "Artista no disponible", Toast.LENGTH_SHORT).show()
                }
            }
        bottomSheet.show(childFragmentManager, "songOptions")
    }

    private fun startVoiceSearch() {
        try {
            isVoiceSearchActive = true
            val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
                putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
                putExtra(RecognizerIntent.EXTRA_LANGUAGE, Locale.getDefault())
                putExtra(RecognizerIntent.EXTRA_PROMPT, "Habla ahora...")
                putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)
            }
            voiceSearchLauncher.launch(intent)
        } catch (_: Exception) {
            isVoiceSearchActive = false
            Toast.makeText(context, "Búsqueda por voz no soportada", Toast.LENGTH_SHORT).show()
        }
    }

    private fun handleVoiceSearchResult(resultCode: Int, data: Intent?) {
        isVoiceSearchActive = false
        if (resultCode == Activity.RESULT_OK && data != null) {
            val results = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)
            if (!results.isNullOrEmpty()) {
                val spokenText = results[0]
                binding.etSearch.setText(spokenText)
                binding.etSearch.setSelection(spokenText.length)
                performSearch(spokenText)
            }
        }
    }

    private fun switchToViewMode(mode: ViewMode) {
        if (currentViewMode == mode) return
        currentViewMode = mode
        // Animación ligera
        binding.rvSearchResults.animate()
            .alpha(0.5f)
            .setDuration(ANIMATION_DURATION / 2)
            .withEndAction {
                binding.rvSearchResults.animate().alpha(1f).setDuration(ANIMATION_DURATION / 2).start()
            }
            .start()
    }

    private fun showLoading(show: Boolean) {
        binding.loadingState.isVisible = show
        if (show) {
            // Al mostrar loading, ocultar todo lo demás
            binding.rvSearchResults.isGone = true
            binding.emptyState.isGone = true
            binding.errorState.isGone = true
        }
        // Cuando show es false, no cambiamos otros estados; quienes llamen a este método
        // deben haber mostrado el estado correcto (resultados, error o vacío).
    }

    private fun showEmptyState() {
        binding.emptyState.isVisible = true
        binding.loadingState.isGone = true
        binding.rvSearchResults.isGone = true
        binding.errorState.isGone = true
    }

    private fun showResults() {
        binding.rvSearchResults.isVisible = true
        binding.emptyState.isGone = true
        binding.loadingState.isGone = true
        binding.errorState.isGone = true
        switchToViewMode(ViewMode.RESULTS)
    }

    private fun showErrorState(title: String, message: String) {
        binding.tvErrorTitle.text = title
        binding.tvErrorMessage.text = message
        binding.errorState.isVisible = true
        binding.emptyState.isGone = true
        binding.loadingState.isGone = true
        binding.rvSearchResults.isGone = true
    }

    private fun showSnackbar(message: String, isError: Boolean = false) {
        val snackbar = Snackbar.make(binding.root, message, Snackbar.LENGTH_SHORT)
        if (isError) {
            // Usa color por defecto de Material si no existe R.color.error
        }
        snackbar.show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        searchJob?.cancel()
        _binding = null
    }
}

package com.arantec.castafiore.ui.viewmodels
import androidx.lifecycle.MutableLiveData import androidx.lifecycle.ViewModel import com.arantec.castafiore.ui.adapters.SearchResultsAdapter
class SearchViewModel : ViewModel() { val query: MutableLiveData<String> = MutableLiveData("") val items: MutableLiveData<List<SearchResultsAdapter.Item>> = MutableLiveData(emptyList()) }

package com.arantec.castafiore.utils

import android.content.Context
import android.graphics.Bitmap
import android.graphics.drawable.Drawable
import android.widget.ImageView
import androidx.fragment.app.Fragment
import com.bumptech.glide.Glide
import com.bumptech.glide.RequestBuilder
import com.bumptech.glide.load.DataSource
import com.bumptech.glide.load.engine.DiskCacheStrategy
import com.bumptech.glide.load.engine.GlideException
import com.bumptech.glide.load.resource.bitmap.CenterCrop
import com.bumptech.glide.load.resource.bitmap.RoundedCorners
import com.bumptech.glide.load.resource.drawable.DrawableTransitionOptions
import com.bumptech.glide.request.RequestListener
import com.bumptech.glide.request.RequestOptions
import com.bumptech.glide.request.target.CustomTarget
import com.bumptech.glide.request.target.Target
import com.bumptech.glide.request.transition.Transition
import com.arantec.castafiore.R

/**
 * Clase utilitaria para manejar la carga optimizada de imágenes con Glide
 */
object ImageLoader {

    /**
     * Opciones de caché optimizado para imágenes de música
     */
    private val musicImageOptions = RequestOptions()
        .diskCacheStrategy(DiskCacheStrategy.ALL) // Cachear tanto la imagen original como las transformadas
        .skipMemoryCache(false) // Usar caché de memoria
        .placeholder(R.drawable.ic_album_placeholder)
        .error(R.drawable.ic_album_placeholder)

    /**
     * Opciones para imágenes de álbum con transición suave
     */
    private val albumImageOptions = RequestOptions()
        .diskCacheStrategy(DiskCacheStrategy.ALL)
        .skipMemoryCache(false)
        .placeholder(R.drawable.ic_album_placeholder)
        .error(R.drawable.ic_album_placeholder)

    /**
     * Opciones para imágenes de artista con esquinas redondeadas
     */
    private val artistImageOptions = RequestOptions()
        .diskCacheStrategy(DiskCacheStrategy.ALL)
        .skipMemoryCache(false)
        .placeholder(R.drawable.ic_person)
        .error(R.drawable.ic_person)
        .circleCrop()

    /**
     * Opciones para thumbnails pequeños (listas)
     */
    private val thumbnailOptions = RequestOptions()
        .diskCacheStrategy(DiskCacheStrategy.ALL)
        .skipMemoryCache(false)
        .placeholder(R.drawable.ic_music_note)
        .error(R.drawable.ic_music_note)
        .override(200, 200) // Tamaño optimizado para thumbnails

    /**
     * Carga una imagen de álbum con transición suave
     */
    fun loadAlbumCover(
        context: Context,
        imageView: ImageView,
        url: String?,
        onSuccess: ((Bitmap) -> Unit)? = null,
        onError: (() -> Unit)? = null
    ) {
        if (url.isNullOrEmpty()) {
            imageView.setImageResource(R.drawable.ic_album_placeholder)
            onError?.invoke()
            return
        }

        Glide.with(context)
            .asBitmap()
            .load(url)
            .apply(albumImageOptions)
            .into(imageView)
    }

    /**
     * Carga una imagen de álbum en un CustomTarget (para fragmentos)
     */
    fun loadAlbumCoverForFragment(
        fragment: Fragment,
        url: String?,
        onSuccess: (Bitmap) -> Unit,
        onError: () -> Unit = {}
    ) {
        if (url.isNullOrEmpty()) {
            onError()
            return
        }

        Glide.with(fragment)
            .asBitmap()
            .load(url)
            .apply(albumImageOptions)
            .into(object : CustomTarget<Bitmap>() {
                override fun onResourceReady(resource: Bitmap, transition: Transition<in Bitmap>?) {
                    onSuccess(resource)
                }

                override fun onLoadCleared(placeholder: Drawable?) {
                    onError()
                }

                override fun onLoadFailed(errorDrawable: Drawable?) {
                    onError()
                }
            })
    }

    /**
     * Carga una imagen de artista circular
     */
    fun loadArtistImage(
        context: Context,
        imageView: ImageView,
        url: String?
    ) {
        Glide.with(context)
            .load(url)
            .apply(artistImageOptions)
            .transition(DrawableTransitionOptions.withCrossFade(250))
            .into(imageView)
    }

    /**
     * Carga una imagen de artista para fragmentos
     */
    fun loadArtistImageForFragment(
        fragment: Fragment,
        imageView: ImageView,
        url: String?
    ) {
        Glide.with(fragment)
            .load(url)
            .apply(artistImageOptions)
            .transition(DrawableTransitionOptions.withCrossFade(250))
            .into(imageView)
    }

    /**
     * Carga un thumbnail pequeño para listas
     */
    fun loadThumbnail(
        context: Context,
        imageView: ImageView,
        url: String?
    ) {
        Glide.with(context)
            .load(url)
            .apply(thumbnailOptions)
            .into(object : CustomTarget<Drawable>() {
                override fun onResourceReady(resource: Drawable, transition: Transition<in Drawable>?) {
                    imageView.setImageDrawable(resource)
                }

                override fun onLoadCleared(placeholder: Drawable?) {
                    imageView.setImageResource(R.drawable.ic_album_placeholder)
                }

                override fun onLoadFailed(errorDrawable: Drawable?) {
                    imageView.setImageResource(R.drawable.ic_album_placeholder)
                }
            })
    }

    /**
     * Carga un thumbnail para fragmentos
     */
    fun loadThumbnailForFragment(
        fragment: Fragment,
        imageView: ImageView,
        url: String?
    ) {
        if (!fragment.isAdded) return // Verificación de seguridad

        Glide.with(fragment)
            .load(url)
            .apply(thumbnailOptions)
            .transition(DrawableTransitionOptions.withCrossFade(200))
            .into(imageView)
    }

    /**
     * Precarga una imagen para mejorar la experiencia
     */
    fun preloadImage(context: Context, url: String?) {
        if (url.isNullOrEmpty()) return

        Glide.with(context)
            .load(url)
            .apply(musicImageOptions)
            .preload()
    }

    /**
     * Limpia el caché de memoria cuando sea necesario
     */
    fun clearMemoryCache(context: Context) {
        Glide.get(context).clearMemory()
    }

    /**
     * Limpia el caché de disco (debe ejecutarse en background thread)
     */
    suspend fun clearDiskCache(context: Context) {
        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            Glide.get(context).clearDiskCache()
        }
    }

    /**
     * Configura Glide para usar un tamaño de caché de memoria más grande
     */
    fun configureGlideCache(context: Context) {
        // Esta configuración se debe hacer en el Application class o GlideModule
        val memoryCacheSize = 1024 * 1024 * 50 // 50MB
        val diskCacheSize = 1024 * 1024 * 250L // 250MB
    }

    /**
     * Construye URL de cover art con parámetros de autenticación
     */
    fun buildCoverArtUrl(
        serverUrl: String,
        albumId: String,
        username: String,
        token: String,
        salt: String,
        size: Int = 300
    ): String {
        return "$serverUrl/rest/getCoverArt.view?id=$albumId&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=$size"
    }

    /**
     * Construye URL de imagen de artista
     */
    fun buildArtistImageUrl(
        serverUrl: String,
        artistId: String,
        username: String,
        token: String,
        salt: String,
        size: Int = 300
    ): String {
        return "$serverUrl/rest/getCoverArt.view?id=$artistId&u=$username&t=$token&s=$salt&v=1.16.1&c=Castafiore&size=$size"
    }
}

